// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address[] memory _tos, uint v) public {
        vm.assume(_tos.length > 0);
        FailingTransferFrom failer = new FailingTransferFrom();
        bool ok;
        try c.transfer(from, address(failer), _tos, v) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(!ok);
    }
}

contract FailingTransferFrom {
    function transferFrom(address, address, uint256) external pure returns (bool) {
        return false;
    }
}
